<?php
namespace Modules\Glitter\NotificationHub\Http\Controllers\Admin;use App\Helpers\ResponseHelper;use App\Http\Controllers\Api\Base\AdminBaseController;use Illuminate\Http\JsonResponse;use Modules\Glitter\NotificationHub\DTO\Admin\ManualRetryData;use Modules\Glitter\NotificationHub\DTO\Admin\NotificationDeadLetterSearchData;use Modules\Glitter\NotificationHub\Http\Requests\Admin\ListNotificationDeadLettersRequest;use Modules\Glitter\NotificationHub\Http\Requests\Admin\ResolveNotificationDeadLetterRequest;use Modules\Glitter\NotificationHub\Http\Requests\Admin\RetryNotificationPlanRequest;use Modules\Glitter\NotificationHub\Http\Resources\Admin\NotificationDeadLetterCollection;use Modules\Glitter\NotificationHub\Http\Resources\Admin\NotificationDeadLetterResource;use Modules\Glitter\NotificationHub\Services\Admin\NotificationHubAdminService;
class NotificationDeadLetterController extends AdminBaseController { public function __construct(private readonly NotificationHubAdminService $service){} public function index(ListNotificationDeadLettersRequest $r):JsonResponse{return ResponseHelper::moduleSuccess('glitter-notification_hub','messages.dead_letters_retrieved',new NotificationDeadLetterCollection($this->service->listDeadLetters(NotificationDeadLetterSearchData::fromArray($r->validated()))));} public function show(string $deadLetter):JsonResponse{return ResponseHelper::moduleSuccess('glitter-notification_hub','messages.dead_letter_retrieved',new NotificationDeadLetterResource($this->service->getDeadLetter($deadLetter)));} public function resolve(ResolveNotificationDeadLetterRequest $r,string $deadLetter):JsonResponse{return ResponseHelper::moduleSuccess('glitter-notification_hub','messages.dead_letter_resolved',new NotificationDeadLetterResource($this->service->resolveDeadLetter($deadLetter,$r->validated('resolution_note'),$r->user()?->id)));} public function retry(RetryNotificationPlanRequest $r,string $deadLetter):JsonResponse{return ResponseHelper::moduleSuccess('glitter-notification_hub','messages.plan_retry_created',$this->service->retryDeadLetter($deadLetter,ManualRetryData::fromArray($r->validated(),$r->user()?->id))->toArray(),201);} }
